13    leapLadder = [0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335];
14
15  function unitOutOfRange(unit, value) {
16    return new Invalid(
17      "unit out of range",
18      `you specified ${value} (of type ${typeof value}) as a ${unit}, which is invalid`
19    );
20  }
```

Lines 100–112 (`hasInvalidWeekData`):

```js
100  export function hasInvalidWeekData(obj) {
101    const validYear = isInteger(obj.weekYear),
102      validWeek = integerBetween(obj.weekNumber, 1, weeksInWeekYear(obj.weekYear)),
103      validWeekday = integerBetween(obj.weekday, 1, 7);
104
105    if (!validYear) {
106      return unitOutOfRange("weekYear", obj.weekYear);
107    } else if (!validWeek) {
108      return unitOutOfRange("week", obj.week);
109    } else if (!validWeekday) {
110      return unitOutOfRange("weekday", obj.weekday);
111    } else return false;
112  }
```

Helpers, `/luxon/src/impl/util.js`:

```js
15  export function isUndefined(o) {
16    return typeof o === "undefined";
17  }
...
23  export function isInteger(o) {
24    return typeof o === "number" && o % 1 === 0;
25  }
...
92  export function integerBetween(thing, bottom, top) {
93    return isInteger(thing) && thing >= bottom && thing <= top;
94  }
...
174  export function weeksInWeekYear(weekYear) {
175    const p1 =
176        (weekYear +
177          Math.floor(weekYear / 4) -
178          Math.floor(weekYear / 100) +
179          Math.floor(weekYear / 400)) %
180        7,
181      last = weekYear - 1,
182      p2 = (last + Math.floor(last / 4) - Math.floor(last / 100) + Math.floor(last / 400)) % 7;
183    return p1 === 4 || p2 === 3 ? 53 : 52;
184  }
```

`/luxon/src/impl/invalid.js` lines 1–13: `Invalid` is a plain class with `reason` and `explanation` fields.

Note: `isUndefined` is **not** imported or used by `conversions.js` (imports are only the 7 names on lines 2–8). `isUndefined` is used in `datetime.js` (e.g. line 676).

### 2. Answer: `weekYear` NOT an integer

**Return value: an `Invalid` instance (a truthy object), NOT `true`.** The function never returns boolean `true`; it returns `false` when valid and an `Invalid` object when invalid.

Trace for e.g. `{ weekYear: 2017.5, weekNumber: 1, weekday: 1 }`:

