/* global test expect */
import { Interval, Settings } from "../../src/luxon";

const inputs = [
  "2007-03-01T13:00:00/2008-05-11T15:30:00",
  "2007-03-01T13:00:00/P1Y2M10DT2H30M",
  "P1Y2M10DT2H30M/2008-05-11T15:30:00",
  "2016-01-01/P1Y",
  "P1Y/2016-01-01",
  "2016-01-01/PT1H",
