];

const run = (flag) => {
  Settings.throwOnInvalid = flag;
  for (const s of inputs) {
    let out;
    try {
      const i = Interval.fromISO(s);
      out = `isValid=${i.isValid} reason=${i.invalidReason}`;
    } catch (e) {
      out = `THREW ${e.constructor.name}: ${e.message}`;
    }
    console.log(`[throwOnInvalid=${flag}]`, JSON.stringify(s), "=>", out);
  }
  Settings.throwOnInvalid = false;
};

test("sweep", () => {
  run(false);
