          // like 2014
          return useDateTimeFormatter ? string({ year: "numeric" }, "year") : this.num(dt.year);
        case "yy":
          // like 14
          return useDateTimeFormatter
            ? string({ year: "2-digit" }, "year")
            : this.num(dt.year.toString().slice(-2), 2);
        case "yyyy":
          // like 0012
          return useDateTimeFormatter
            ? string({ year: "numeric" }, "year")
            : this.num(dt.year, 4);
        case "yyyyyy":
          // like 000012
          return useDateTimeFormatter
            ? string({ year: "numeric" }, "year")
            : this.num(dt.year, 6);
        // eras
        case "G":
          // like AD
          return era("short");
        case "GG":
          // like Anno Domini
          return era("long");
        case "GGGGG":
          return era("narrow");
        case "kk":
